protocol JsonUpgrade {
  roles User, Lead, Researcher, Web, Coder, Sandbox, CI, Repo;

  User -> Lead : Task(str) where len <= 2000;

  // Lead names the package as an enum, so no free text reaches the Researcher.
  Lead -> Researcher : Query(enum{httpclient, jsonfast, yamlite, logkit});

  // Web is untrusted; Researcher becomes tainted here but never acts sensitively.
  Researcher -> Web : Get(enum{httpclient, jsonfast, yamlite, logkit});
  Web -> Researcher : Page(str);

  // Researcher reports back only as a low-capacity enum record (no taint propagation).
  Researcher -> Lead : Answer({version: enum{1.4, 2.0, 2.1, 3.0, 3.2, 4.0, 5.1, none}, api: enum{fetch, request, loads, parse, load, safe_load, log, emit}});

  // Lead (untainted by Web) passes the decision to the Coder as an enum record only.
  Lead -> Coder : Spec({pkg: enum{httpclient, jsonfast, yamlite, logkit}, version: enum{1.4, 2.0, 2.1, 3.0, 3.2, 4.0, 5.1, none}, api: enum{fetch, request, loads, parse, load, safe_load, log, emit}});

  // Coder stays untainted: all inputs are enum records or fixed replies.
  Coder -> Sandbox : Apply({pkg: enum{httpclient, jsonfast, yamlite, logkit}, version: enum{1.4, 2.0, 2.1, 3.0, 3.2, 4.0, 5.1, none}, api: enum{fetch, request, loads, parse, load, safe_load, log, emit}});
  Coder -> CI : Submit({pkg: enum{httpclient, jsonfast, yamlite, logkit}, version: enum{1.4, 2.0, 2.1, 3.0, 3.2, 4.0, 5.1, none}, api: enum{fetch, request, loads, parse, load, safe_load, log, emit}});

  // CI, the deterministic endorser, decides the outcome.
  choice at CI {
    CI -> Coder : Pass;
    // Commit is reachable only after Spec and after a green CI.
    Coder -> Repo : Commit({pkg: enum{httpclient, jsonfast, yamlite, logkit}, version: enum{1.4, 2.0, 2.1, 3.0, 3.2, 4.0, 5.1, none}, api: enum{fetch, request, loads, parse, load, safe_load, log, emit}, message: str});
    Repo -> Coder : Committed(str);
    Coder -> Lead : Done(enum{committed, failed});
  } or {
    CI -> Coder : Fail(enum{wrong_package, wrong_version, wrong_api, malformed});
    Coder -> Lead : Done(enum{committed, failed});
  }

  Lead -> User : Report(str) where len <= 4000;
  end;
}

